// Revenue conversion fix: ensure paidEvents increments on successful checkout
// This module intercepts checkout completion and triggers revenue event

const revenueModule = require('./revenue');

module.exports = function(app) {
  app.post('/api/checkout/complete', (req, res, next) => {
    const originalSend = res.send.bind(res);
    res.send = function(body) {
      try {
        const data = JSON.parse(body);
        if (data && data.success) {
          revenueModule.recordEvent({
            type: 'paid',
            amount: data.amount || 0,
            currency: data.currency || 'USD',
            timestamp: Date.now()
          });
        }
      } catch (e) {
        console.error('Revenue conversion fix parse error:', e.message);
      }
      return originalSend(body);
    };
    next();
  });
};
